package com.eidolon.sc.mobile;
import java.nio.*;import java.util.*;import org.json.*;
/** Deterministic cancellation/format contracts, not an Android audio or paid-service test. */
public final class CallTests {
 static void check(boolean b,String n){if(!b)throw new AssertionError(n);System.out.println("PASS "+n);}
 public static void main(String[] args)throws Exception{
  CallEpoch old=new CallEpoch("call-a");long a=old.next();check(old.current("call-a",a),"live call owns its current turn");check(!old.current("call-b",a),"another call identity cannot claim an old callback");long b=old.next();check(!old.current("call-a",a)&&old.current("call-a",b),"interrupting a turn fences recognition/model/audio callbacks");old.end();check(!old.current("call-a",b),"hangup fences every outstanding stage");CallEpoch next=new CallEpoch("call-b");long c=next.next();check(next.current("call-b",c)&&!old.current("call-a",a),"late result cannot enter a newly dialled call");
  CallEpoch concurrent=new CallEpoch("concurrent");long before=concurrent.next();Thread stop=new Thread(concurrent::end);stop.start();stop.join();check(!concurrent.current("concurrent",before),"worker observes cancellation across threads");
  byte[] pcm={0,0,1,0,-1,127};byte[] wav=CallHttpAsr.wav(pcm);ByteBuffer bytes=ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);check(wav.length==pcm.length+44&&new String(wav,0,4,"US-ASCII").equals("RIFF")&&bytes.getInt(24)==16000&&bytes.getInt(40)==pcm.length,"ASR adapter makes valid bounded mono 16k WAV in memory");check(Arrays.equals(Arrays.copyOfRange(wav,44,wav.length),pcm),"ASR WAV transport preserves PCM bytes without an audio file");
  check(CallHttpAsr.endpoint("https://example.com/v1/audio/transcriptions").startsWith("https://"),"explicit compatible HTTPS ASR endpoint accepted");boolean rejected=false;try{CallHttpAsr.endpoint("http://example.com/transcribe?key=secret");}catch(Exception good){rejected=true;}check(rejected,"insecure or query-key ASR endpoint rejected");
  Set<String> known=Collections.singleton("mano");JSONObject row=new JSONObject().put("id","call1").put("character","mano").put("session","session1").put("state","ended").put("connectedAt",100).put("endedAt",200).put("turnId",2).put("pending","");CallStore.validateBackup(new JSONObject().put("calls",new JSONArray().put(row)),known);check(!CallStore.live(row),"ended call metadata validates and is no longer busy");row.put("state","thinking");check(CallStore.live(row),"generating call remains busy while ownership is held");
  JSONObject invalid=new JSONObject(row.toString()).put("character","other");rejected=false;try{CallStore.validateBackup(new JSONObject().put("calls",new JSONArray().put(invalid)),known);}catch(Exception good){rejected=true;}check(rejected,"backup rejects unknown call role");
  CallEpoch heard=new CallEpoch("heard");long turn=heard.next();check(!heard.commitOnce("heard",turn),"unplayed response cannot acquire a heard-commit token");heard.audioStarted("heard",turn);check(heard.commitOnce("heard",turn)&&!heard.commitOnce("heard",turn),"fully played callback can acquire one commit token only");long nextTurn=heard.next();check(!heard.commitOnce("heard",nextTurn),"next turn requires its own real playback start");heard.audioStarted("heard",nextTurn);heard.end();check(!heard.commitOnce("heard",nextTurn),"hangup during playback prevents later heard commit");
  check(CallAudioText.forVoice("<zh>你好。</zh>",false).equals("你好。"),"Chinese-only phone speaks Chinese instead of rejecting a subtitle");check(FishClient.speech(CallAudioText.forVoice("<ja>こんにちは</ja><zh>你好</zh>",true)).equals("こんにちは"),"bilingual phone still speaks Japanese only");
  long wall=java.time.Instant.parse("2026-10-30T16:00:30Z").toEpochMilli();check(java.time.Instant.ofEpochMilli(CallClock.utteranceAt(wall,90000,30000)).atZone(java.time.ZoneId.of("Asia/Shanghai")).toLocalDate().toString().equals("2026-10-30"),"ASR received after midnight retains the prior-day speech timestamp");
  boolean pending=BackupValidator.sequence(false,new JSONObject().put("role","user"));pending=BackupValidator.sequence(pending,new JSONObject().put("role","user"));check(pending,"interrupted or batched user speech remains a valid unfinished backup sequence");pending=BackupValidator.sequence(pending,new JSONObject().put("role","assistant").put("reachOut",true));check(pending&&!BackupValidator.sequence(pending,new JSONObject().put("role","assistant")),"proactive contact does not consume an ordinary pending reply in backup validation");rejected=false;try{BackupValidator.sequence(false,new JSONObject().put("role","assistant"));}catch(Exception good){rejected=true;}check(rejected,"backup still rejects an assistant response with no source user turn");
 }
}
